sB,CAJtB,eAAgB,CAEhB,YAAa,CADb,iBAKJ,CAEA,aAII,yBAA0B,CAF1B,YAAa,CACb,gBAAiB,CAFjB,UAIJ,CAEA,YACI,eAAgB,CAChB,iBACJ,CAEI,eAEI,UAAc,CADd,gBAEJ,CAEA,cAEI,UAAW,CADX,cAAe,CAEf,cACJ,CAEA,cAGI,aAAc,CAFd,oBAAqB,CAIrB,eAAiB,CAHjB,gBAAkB,CAElB,oBAEJ,CAEI,oBACI,yBACJ,CAGR,yBACI,YACI,YACJ,CAEA,YAEI,QAAS,CADT,yBAEJ,CAEA,YACI,qBAAsB,CAEtB,YAAa,CADb,iBAEJ,CAEA,aAII,iBAAkB,CAFlB,WAAY,CACZ,kBAAmB,CAFnB,SAIJ,CAEA,eACI,gBACJ,CAMA,4BACI,cACJ,CACJ,CAGA,gDACI,oBACI,YACJ,CACJ,CCtGA,KAKI,qBAAsB,CAJtB,4BAA8B,CAE9B,QAAS,CACT,SAAU,CAFV,iBAIJ,CAGA,QACI,qBAAsB,CACtB,YACJ,CAEA,UACI,UAAY,CAGZ,cAAe,CADf,aAAc,CADd,oBAGJ,CAEI,gBACI,yBACJ,CAGJ,WACI,YACJ,CAEA,cAII,kBAAmB,CADnB,eAAgB,CADhB,eAAgB,CADhB,UAIJ,CAGA,qCACI,YACJ,CAGA,KAGI,qBAAsB,CACtB,iBACJ,CASA,yBACI,KACI,WACJ,CAEA,cACI,SACJ,CAEA,UACI,cAAe,CACf,WACJ,CAEA,cAGI,aAAS,CAFT,YAAa,CAEb,QAAS,CADT,yBAEJ,CAEA,cACI,YAAa,CACb,iBACJ,CAEA,IAGI,kBAAmB,CADnB,WAAY,CADZ,SAGJ,CACJ,CCxFA,KAII,wBAAyB,CACzB,UAAW,CAFX,6BAAiC,CAFjC,QAAS,CACT,SAIJ,CAEA,eACI,YAAa,CACb,qBAAsB,CACtB,gBACJ","sources":["styles/Header.css","styles/Footer.css","styles/HomePage.css","styles/AboutPage.css","styles/PlacePage.css","styles/FoodPage.css","styles/HotelPage.css","styles/App.css","App.css"],"sourcesContent":["/* Header Container */\r\n.header {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    background: linear-gradient(90deg, #003366, #0056b3); /* Gradient background */\r\n    padding: 10px 20px; /* Spacing for breathing room */\r\n    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); /* Soft shadow for depth */\r\n    color: white; /* White text for contrast */\r\n    font-family: 'Arial', sans-serif;\r\n    position: sticky; /* Sticky at the top */\r\n    top: 0;\r\n    z-index: 1000;\r\n}\r\n\r\n/* Logo Styling */\r\n.logo-link {\r\n    text-decoration: none;\r\n    font-size: 1.8rem;\r\n    font-weight: bold;\r\n    letter-spacing: 1px;\r\n    color: white;\r\n    display: flex;\r\n    align-items: center;\r\n}\r\n\r\n/* Navigation Bar */\r\n.navbar {\r\n    display: flex;\r\n    gap: 15px; /* Space between navigation links */\r\n}\r\n\r\n    .navbar a {\r\n        color: white;\r\n        text-decoration: none;\r\n        padding: 8px 12px;\r\n        border-radius: 5px; /* Rounded buttons */\r\n        font-size: 1rem;\r\n        font-weight: 500;\r\n        transition: background-color 0.3s ease, transform 0.2s ease; /* Smooth transitions */\r\n    }\r\n\r\n        .navbar a:hover {\r\n            background-color: #ffffff33; /* Subtle highlight on hover */\r\n            transform: scale(1.05); /* Slight zoom effect */\r\n        }\r\n\r\n.header {\r\n    transition: all 0.3s ease-in-out;\r\n}\r\n\r\n.header {\r\n    width: 100%;\r\n    background: linear-gradient(90deg, #003366, #0056b3); /* Gradient background */\r\n    padding: 10px 20px;\r\n    position: sticky;\r\n    top: 0;\r\n    left: 0;\r\n    z-index: 1000;\r\n    color: white;\r\n    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\r\n    transition: all 0.3s ease-in-out;\r\n}\r\n\r\n\r\n.navbar a:hover {\r\n    background-color: rgba(255, 255, 255, 0.2);\r\n    color: #fff;\r\n    transform: scale(1.05);\r\n}\r\n\r\n\r\n/* Responsive Design */\r\n@media (max-width: 768px) {\r\n    .navbar {\r\n        display: none;\r\n    }\r\n\r\n    .hamburger-menu {\r\n        display: block;\r\n        position: absolute;\r\n        top: 10px;\r\n        right: 10px;\r\n        font-size: 1.5rem;\r\n        cursor: pointer;\r\n    }\r\n\r\n    .navbar.show {\r\n        display: flex;\r\n        flex-direction: column;\r\n        background: #0056b3;\r\n        width: 100%;\r\n        position: absolute;\r\n        top: 50px;\r\n        left: 0;\r\n        padding: 10px 0;\r\n        z-index: 1000;\r\n    }\r\n\r\n    .navbar a {\r\n        color: white;\r\n        padding: 10px;\r\n        text-align: center;\r\n    }\r\n}\r\n\r\n/* ��͹ Hamburger Menu ��˹�Ҩ��ʡ��ͻ */\r\n@media (min-width: 1025px) {\r\n    .hamburger-menu {\r\n        display: none; /* ��͹���� Hamburger */\r\n    }\r\n\r\n    .navbar {\r\n        display: flex !important; /* �ʴ� Navbar Ẻ��� */\r\n    }\r\n}\r\n\r\n\r\n\r\n\r\n\r\n",".footer {\r\n    text-align: center;\r\n    padding: 1rem 0;\r\n    background-color: #002a5c;\r\n    color: white;\r\n    font-size: 0.9rem;\r\n}\r\n\r\n.footer {\r\n    width: 100%;\r\n    background-color: #002a5c;\r\n    color: white;\r\n    text-align: center;\r\n    padding: 1rem 0;\r\n    position: fixed;\r\n    bottom: 0;\r\n    left: 0;\r\n    z-index: 1000;\r\n}\r\n\r\n\r\n/* Responsive Design */\r\n@media (max-width: 768px) {\r\n    .footer {\r\n        font-size: 0.8rem; /* Ŵ��Ҵ��ͤ��� */\r\n        padding: 0.5rem; /* Ŵ Padding */\r\n        text-align: center; /* �Ѵ��ͤ�����������ҧ */\r\n    }\r\n}\r\n\r\n","/* General styling for the home page */\r\n.home {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    min-height: 100vh;\r\n    background-color: rgba(255, 255, 255, 0.7);\r\n    text-align: center;\r\n}\r\n\r\n.hero {\r\n    margin-top: 0; /* Remove unwanted margin */\r\n    width: 100%;\r\n    padding: 2rem;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 2rem;\r\n}\r\n\r\n.hero-content {\r\n    margin-top: 0rem; /* Fine-tune space if header adds extra gap */\r\n    padding-top: 0rem;\r\n    background-color: rgba(255, 255, 255, 0.9);\r\n    padding: 2rem;\r\n    border-radius: 30px;\r\n    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);\r\n    width: 90%;\r\n    max-width: 650px;\r\n    text-align: center;\r\n    color: #003366;\r\n}\r\n\r\n    .hero-content h1 {\r\n        font-size: 3.5rem;\r\n        margin-bottom: 0rem;\r\n        font-weight: bold;\r\n    }\r\n\r\n    .hero-content p {\r\n        font-size: 1.2rem;\r\n        margin-bottom: 1.5rem;\r\n        line-height: 1.6;\r\n    }\r\n\r\n.hero-buttons .button {\r\n    background-color: #0056b3; /* �վ����ѧ�ͧ���� */\r\n    color: white; /* �բ�ͤ��� */\r\n    padding: 10px 20px;\r\n    border: none;\r\n    border-radius: 5px;\r\n    font-size: 16px;\r\n    font-weight: bold;\r\n    text-decoration: none;\r\n    display: inline-block;\r\n    margin: 10px;\r\n    cursor: pointer;\r\n    transition: background-color 0.3s ease-in-out, transform 0.2s ease;\r\n}\r\n\r\n    .hero-buttons .button:hover {\r\n        background-color: #003366; /* ������� Hover */\r\n        transform: scale(1.05); /* ��������� Hover */\r\n    }\r\n\r\n\r\n.home-video {\r\n    margin-top: 1rem;\r\n    width: 90%;\r\n    max-width: 600px;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n}\r\n\r\niframe {\r\n    width: 100%;\r\n    height: 350px;\r\n    border-radius: 10px;\r\n    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);\r\n}\r\n\r\n/* Polaroid Style */\r\n.polaroid {\r\n    position: absolute;\r\n    width: 150px;\r\n    text-align: center;\r\n    background: white;\r\n    padding: 10px;\r\n    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);\r\n    border-radius: 10px;\r\n    transform: rotate(-5deg);\r\n}\r\n\r\n    .polaroid img {\r\n        width: 100%;\r\n        height: auto;\r\n        border-radius: 5px;\r\n    }\r\n\r\n    .polaroid p {\r\n        font-family: 'Caveat', cursive;\r\n        font-size: 1.2rem;\r\n        color: #333;\r\n        margin-top: 10px;\r\n    }\r\n\r\n    /* Left Polaroid */\r\n    .polaroid.left {\r\n        top: 20%;\r\n        left: 5%;\r\n        transform: rotate(-10deg);\r\n    }\r\n\r\n    /* Right Polaroid */\r\n    .polaroid.right {\r\n        top: 20%;\r\n        right: 5%;\r\n        transform: rotate(10deg);\r\n    }\r\n    /* Bottom Polaroids */\r\n    .polaroid.left.bottom {\r\n        top: 80%;\r\n        left: 10%;\r\n        transform: rotate(8deg);\r\n    }\r\n\r\n    .polaroid.right.bottom {\r\n        top: 70%;\r\n        right: 10%;\r\n        transform: rotate(-10deg);\r\n    }\r\n\r\n\r\n/* ��͹ Polaroid ����������˹�Ҩ���Ͷ�� */\r\n@media (max-width: 768px) {\r\n    .polaroid-container {\r\n        display: none; /* ��͹������ */\r\n    }\r\n}\r\n\r\n/* ��Ѻ Hero Section �������СѺ��Ͷ�� */\r\n@media (max-width: 768px) {\r\n    .hero-content {\r\n        padding: 1rem;\r\n        width: 100%;\r\n        text-align: center;\r\n    }\r\n\r\n    .hero-buttons {\r\n        flex-direction: column;\r\n        gap: 10px;\r\n    }\r\n\r\n    iframe {\r\n        width: 100%;\r\n        height: 200px;\r\n    }\r\n}\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n",".about-page {\n    padding: 3rem;\n}\n\n.about-header {\n    text-align: center;\n    margin-bottom: 3.5rem;\n}\n\n    .about-header h1 {\n        font-size: 2.9rem; /* Increased font size by 15% */\n        color: #002a5c;\n    }\n\n    .about-header p {\n        font-size: 1.38rem; /* Increased font size by 15% */\n        color: #666;\n    }\n\n.about-section {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 2.5rem; /* Reduced gap for better balance */\n    margin-bottom: 3.5rem; /* Adjusted spacing between sections */\n    align-items: center;\n}\n\n    .about-section img {\n        flex: 1;\n        max-width: 550px; /* Increased size by 10% */\n        height: auto;\n        aspect-ratio: 16/9;\n        border-radius: 10px;\n        box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.15); /* Slightly stronger shadow */\n        object-fit: cover;\n    }\n\n.about-content {\n    flex: 1;\n    min-width: 320px;\n}\n\n    .about-content h2 {\n        font-size: 2.07rem; /* Increased font size by 15% */\n        color: #002a5c;\n        margin-bottom: 1.5rem;\n        text-align: center; /* Center align heading */\n    }\n\n    .about-content p {\n        font-size: 1.15rem; /* Increased font size by 15% */\n        color: #333;\n        line-height: 1.8;\n        margin-bottom: 1.5rem; /* Adjusted paragraph spacing */\n        text-align: left; /* Keep paragraph aligned to the left for readability */\n    }\n\n/* Responsive Design */\n@media (max-width: 768px) {\n    .about-page {\n        padding: 1rem; /* Ŵ Padding ���ʹաѺ��Ͷ�� */\n    }\n\n    .about-header {\n        text-align: center;\n        margin-bottom: 2rem;\n    }\n\n        .about-header h1 {\n            font-size: 2rem; /* Ŵ��Ҵ�͹�����Ͷ�� */\n        }\n\n        .about-header p {\n            font-size: 1rem;\n        }\n\n    .about-section {\n        flex-direction: column; /* �Ѵ���ǵ�����Ͷ�� */\n        text-align: center;\n        gap: 1.5rem; /* Ŵ������ҧ */\n    }\n\n        .about-section img {\n            max-width: 100%; /* ����ٻ�Ҿ��������� */\n            height: auto;\n            margin-bottom: 1rem;\n        }\n\n    .about-content {\n        text-align: center;\n        padding: 0 1rem; /* ���� Padding �ͺ��ͤ��� */\n    }\n\n        .about-content h2 {\n            font-size: 1.5rem; /* Ŵ��Ҵ��Ǣ�� */\n        }\n\n        .about-content p {\n            font-size: 1rem;\n            line-height: 1.6;\n        }\n}\n\n\n","\r\n.place-page {\r\n    padding: 2rem;\r\n    text-align: center;\r\n    background-color: #f9f9f9;\r\n}\r\n\r\n    .place-page h1 {\r\n        font-size: 2.5rem;\r\n        color: #002a5c;\r\n        margin-bottom: 1rem;\r\n    }\r\n\r\n    .place-page p {\r\n        font-size: 1.2rem;\r\n        color: #666;\r\n        margin-bottom: 2rem;\r\n    }\r\n\r\n.place-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\r\n    gap: 2rem;\r\n    justify-content: center;\r\n}\r\n\r\n.place-card {\r\n    background: #fff;\r\n    border-radius: 8px;\r\n    overflow: hidden;\r\n    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\r\n    transition: transform 0.3s, box-shadow 0.3s;\r\n}\r\n\r\n    .place-card:hover {\r\n        transform: translateY(-5px);\r\n        box-shadow: 0 6px 12px rgba(0, 0, 0, 0.2);\r\n    }\r\n\r\n    .place-card img {\r\n        width: 100%;\r\n        height: 150px;\r\n        object-fit: cover;\r\n        border-bottom: 1px solid #ddd;\r\n    }\r\n\