r;\r\n    padding: 1rem;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n}\r\n\r\n.hotel-image {\r\n    width: 100%;\r\n    height: 200px;\r\n    object-fit: cover;\r\n    border-radius: 8px 8px 0 0;\r\n}\r\n\r\n.hotel-info {\r\n    margin-top: 1rem;\r\n    text-align: center;\r\n}\r\n\r\n    .hotel-info h2 {\r\n        font-size: 1.5rem;\r\n        color: #003366;\r\n    }\r\n\r\n    .hotel-info p {\r\n        font-size: 1rem;\r\n        color: #555;\r\n        margin: 0.5rem 0;\r\n    }\r\n\r\n    .hotel-info a {\r\n        display: inline-block;\r\n        margin-top: 0.5rem;\r\n        color: #0056b3;\r\n        text-decoration: none;\r\n        font-weight: bold;\r\n    }\r\n\r\n        .hotel-info a:hover {\r\n            text-decoration: underline;\r\n        }\r\n\r\n/* Responsive Design */\r\n@media (max-width: 768px) {\r\n    .hotel-page {\r\n        padding: 1rem; /* Ŵ Padding ���Ͷ�� */\r\n    }\r\n\r\n    .hotel-list {\r\n        grid-template-columns: 1fr; /* ���������§�ǵ�� */\r\n        gap: 1rem;\r\n    }\r\n\r\n    .hotel-card {\r\n        flex-direction: column; /* �Ѵ�������ǵ�� */\r\n        text-align: center;\r\n        padding: 1rem;\r\n    }\r\n\r\n    .hotel-image {\r\n        width: 90%; /* Ŵ��Ҵ�ٻ�Ҿ */\r\n        height: auto;\r\n        margin-bottom: 1rem;\r\n        border-radius: 8px;\r\n    }\r\n\r\n    .hotel-info h2 {\r\n        font-size: 1.2rem; /* Ŵ��Ҵ��Ǣ�� */\r\n    }\r\n\r\n    .hotel-info p {\r\n        font-size: 1rem; /* Ŵ��Ҵ��ͤ��� */\r\n    }\r\n\r\n    .hotel-info a {\r\n        font-size: 1rem; /* Ŵ��Ҵ�ԧ�� */\r\n    }\r\n}\r\n\r\n/* ����Ѻ˹�Ҩ͢�Ҵ��ҧ (Tablet/iPad) */\r\n@media (min-width: 768px) and (max-width: 1024px) {\r\n    .polaroid-container {\r\n        display: none; /* ��͹ Polaroid */\r\n    }\r\n}\r\n\r\n","/* App Layout */\r\n.app {\r\n    font-family: Arial, sans-serif;\r\n    text-align: center;\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n}\r\n\r\n/* Navbar */\r\n.navbar {\r\n    background-color: #333;\r\n    padding: 10px;\r\n}\r\n\r\n.nav-link {\r\n    color: white;\r\n    text-decoration: none;\r\n    margin: 0 15px;\r\n    font-size: 18px;\r\n}\r\n\r\n    .nav-link:hover {\r\n        text-decoration: underline;\r\n    }\r\n\r\n/* Home Page */\r\n.home-page {\r\n    padding: 20px;\r\n}\r\n\r\n.penang-image {\r\n    width: 100%;\r\n    max-width: 600px;\r\n    margin-top: 20px;\r\n    border-radius: 10px;\r\n}\r\n\r\n/* Food, Places, and Hotels Pages */\r\n.food-page, .places-page, .hotels-page {\r\n    padding: 20px;\r\n}\r\n/* Reset margin and padding globally */\r\n/* Remove margin and padding globally */\r\nbody {\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n    overflow-x: hidden; /* ��ͧ�ѹ�������͹��ҹ��ҧ */\r\n}\r\n\r\n.app-container {\r\n    display: flex;\r\n    flex-direction: column;\r\n    min-height: 100vh;\r\n}\r\n\r\n\r\n@media (max-width: 768px) {\r\n    .app {\r\n        padding: 5px;\r\n    }\r\n\r\n    .penang-image {\r\n        width: 90%; /* Adjust image for smaller screens */\r\n    }\r\n\r\n    .nav-link {\r\n        font-size: 14px;\r\n        padding: 5px;\r\n    }\r\n\r\n    .content-grid {\r\n        display: grid;\r\n        grid-template-columns: 1fr;\r\n        gap: 1rem;\r\n    }\r\n\r\n    .content-item {\r\n        padding: 10px;\r\n        text-align: center;\r\n    }\r\n\r\n    img {\r\n        width: 90%;\r\n        margin: auto;\r\n        border-radius: 10px;\r\n    }\r\n}\r\n\r\n\r\n","body {\r\n    margin: 0;\r\n    padding: 0;\r\n    font-family: 'Roboto', sans-serif;\r\n    background-color: #f9f9f9;\r\n    color: #333;\r\n}\r\n\r\n.app-container {\r\n    display: flex;\r\n    flex-direction: column;\r\n    min-height: 100vh;\r\n}\r\n"],"names":[],"sourceRoot":""}